-- EXPORT GENERATOR v2 -- reads the CATALOG ONLY (no row of data) and WRITES TEXT FILES. Run by the owner on production, READ-ONLY session, from the folder that
-- holds this file (and, from the second pass, reviewed-columns.sql):
--   PGOPTIONS="-c default_transaction_read_only=on" psql "$PROD_READONLY_URL" -X -f export-generate.sql
-- A read-only session cannot create temp objects, so the rule CTE is repeated in every query (generated by one builder; keep them identical).
--
-- TWO PASSES. PASS 1 (no reviewed-columns.sql yet): every column is UNREVIEWED, so export-run.psql is a BLOCKED stub (it prints why and fails; it exports nothing) and
--   rule-report.txt lists EVERY column of EVERY public table with its proposed rule, including KEEP, as 'table|column|type|RULE', plus 'TABLE|name|DATA' (or SKIP) lines.
--   reviewed-candidate.sql holds the same list wrapped as SQL. Review the list; change a rule if a column is more sensitive than proposed.
-- PASS 2: save the reviewed list as reviewed-columns.sql (the wrapper below) and run the generator again. The rule USED for a column is the REVIEWED one.
--   A column (or table) is unreviewed when it is missing from the reviewed list, its type changed since the review, or its reviewed rule cannot apply to its type.
--   While ANY unreviewed column or table exists: export-run.psql and load.psql are blocked stubs, and unreviewed-columns.txt names each one with the reason.
--   Entries of the reviewed list that no longer match the catalog are written to stale-reviewed.txt (information only).
--
-- reviewed-columns.sql format (what reviewed-candidate.sql already is):
--     select $rev$
--     table|column|type|RULE            (RULE = KEEP | SECRET | BLOB | PII | FREETEXT | JSONALLOW)
--     JSONKEEP|table|column|path|kind    (allowlist lines for JSONALLOW columns, see below)
--     TABLE|name|DATA  (or SKIP)        (DATA = rows exported, SKIP = structure only)
--     $rev$ as reviewed \gset
--
-- RULES (what each does; the proposal is made by name patterns, the REVIEWED file decides):
--   SECRET  non-null value -> placeholder derived from the ROW's ctid, never from the secret (nothing derived from a low-entropy secret leaves the server); *_hash columns get a 64-hex placeholder (digest-format CHECKs); NULL stays NULL
--   BLOB    '{}' / 'redacted' / empty bytea (nullness kept)
--   PII     deterministic placeholder (emails end in @example.invalid; inet -> 0.0.0.0)
--   FREETEXT placeholder
--   JSONALLOW json/jsonb ALLOWLIST: only the paths listed in the reviewed file as 'JSONKEEP|table|column|path|kind' survive; EVERYTHING else is dropped (every other key, including dynamic keys, every other value, numbers, strings,
--             containers); the count of dropped entries is kept as {"_redacted": n}. path = key | [].key (arrays of objects) | . (a top-level scalar). kind = KEEP (any value, reviewer attests) | NUM | BOOL | UUID | TS | ENUM:a,b,c
--             (the value is kept only if it has that type/shape). Proposed for every json/jsonb column not SECRET or BLOB, with NO JSONKEEP lines (so the proposal drops everything until the owner lists paths).
--   GUARDS (export-run.psql, checked inside the same read-only transaction BEFORE the first \copy; a failed guard writes no data file):
--     KEEP-GUARD  a KEEP path that holds object/array values, or mixes value types, stops the export.
--     SEQ-GUARD   a role without SELECT on a public sequence stops the export: pg_sequences would show no value for it and the sequence state would be lost silently.
--     RLS-GUARD   a role without BYPASSRLS that is not the owner of a public table with row security (or whose table forces RLS) stops the export:
--                 a row-filtered export would be partial and its _counts.csv would agree with it. Tested: refused with no data files; passes for a SELECT-only BYPASSRLS role with counts equal to the owner's.
--   Known limit: the guards read only the role's own privileges and policies; they do not judge which keys or values are sensitive (that is the reviewed file).
--   KEEP    exported as is: amounts, dates, statuses, codes, keys, foreign keys, booleans, enums (what the upgrade test needs)
-- Proposal patterns: SECRET  secret|token|hmac|password|passwd|credential|api_key|private_key|otp|passcode|salt|nonce + code_hash,token_hash,credential_hash,installation_id_hash
--   BLOB payload|^raw$|raw_|_raw$|response|request_body|headers|body$|qr_payload (not names ending _hash or _fingerprint: those are digests with format CHECKs) ; PII full_name|first_name|last_name|phone|phone_number|mobile|email|work_email|contact_email|
--   billing_address|address|guest_name|plate_number|normalized_plate|ip_address|national_id|id_number|passport_number|whatsapp ; FREETEXT description|note|notes|memo|comment|
--   comments|message|remark|remarks|reason ; SKIP-DATA tables named *raw*, *staging*, *rate_limit*.
-- auth: passwords, sessions, tokens, MFA and identities are never exported; auth.users goes out as id, created_at and a masked email only.
-- Every redaction happens INSIDE the SELECT executed on the server, in ONE repeatable-read read-only transaction: the file is created with placeholders only.

\set ON_ERROR_STOP on
\pset tuples_only on
\pset format unaligned
\pset footer off
\set reviewed ''
\set ON_ERROR_STOP off
\i reviewed-columns.sql
\set ON_ERROR_STOP on

\o export-run.psql
with rh_cols as (
  select c.relname as t, a.attnum, a.attname as col, format_type(a.atttypid, a.atttypmod) as ty, ty.typname as tn,
    case
      when ty.typname in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb')
       and (a.attname ~* '(secret|token|hmac|password|passwd|credential|api_key|private_key|otp|passcode|salt|nonce)'
            or a.attname in ('code_hash','token_hash','credential_hash','installation_id_hash')) then 'SECRET'
      when ty.typname in ('json','jsonb','text','varchar','bytea')
       and a.attname ~* '(payload|^raw$|raw_|_raw$|response|request_body|headers|body$|qr_payload)'
       and a.attname !~* '(_hash|_fingerprint)$' then 'BLOB'
      when ty.typname in ('text','varchar','bpchar','citext','inet')
       and a.attname ~* '^(full_name|first_name|last_name|phone|phone_number|mobile|email|work_email|contact_email|billing_address|address|guest_name|plate_number|normalized_plate|ip_address|national_id|id_number|passport_number|whatsapp)$' then 'PII'
      when ty.typname in ('text','varchar','bpchar','citext')
       and a.attname ~* '^(description|note|notes|memo|comment|comments|message|remark|remarks|reason)$' then 'FREETEXT'
      when ty.typname in ('json','jsonb') then 'JSONALLOW'
      else 'KEEP'
    end as proposed
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace and n.nspname = 'public'
  join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
  join pg_type ty on ty.oid = a.atttypid
  where c.relkind in ('r','p')
), rev as (
  select split_part(l, '|', 1) as t, split_part(l, '|', 2) as col, split_part(l, '|', 3) as ty, upper(trim(split_part(l, '|', 4))) as rule
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l <> '' and l !~ '^#' and l !~ '^TABLE[|]' and l !~ '^JSONKEEP[|]'
), revj as (
  select split_part(l, '|', 2) as t, split_part(l, '|', 3) as col, split_part(l, '|', 4) as path, trim(split_part(l, '|', 5)) as kind
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^JSONKEEP[|]'
), revt as (
  select split_part(l, '|', 2) as t, upper(trim(split_part(l, '|', 3))) as mode
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^TABLE[|]'
), rh_eff as (
  select k.t, k.attnum, k.col, k.ty, k.tn, k.proposed, r.rule as reviewed_rule,
    (select string_agg(format('(%L,%L)', j.path, j.kind), ',') from revj j where j.t = k.t and j.col = k.col) as allow,
    case
      when r.rule is null then null
      when r.rule = 'KEEP' then 'KEEP'
      when r.rule = 'SECRET'   and k.tn in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb') then 'SECRET'
      when r.rule = 'BLOB'     and k.tn in ('json','jsonb','text','varchar','bytea') then 'BLOB'
      when r.rule = 'PII'      and k.tn in ('text','varchar','bpchar','citext','inet') then 'PII'
      when r.rule = 'FREETEXT' and k.tn in ('text','varchar','bpchar','citext') then 'FREETEXT'
      when r.rule = 'JSONALLOW' and k.tn in ('json','jsonb') then 'JSONALLOW'
      else null
    end as eff
  from rh_cols k left join rev r on r.t = k.t and r.col = k.col and r.ty = k.ty
), rh_exprs as (
  select t, attnum, col, eff, tn, allow,
    case eff
      when 'KEEP' then format('%I', col)
      when 'SECRET' then case tn
          when 'uuid'  then format('case when %1$I is null then null else md5(ctid::text || %2$L)::uuid end as %1$I', col, col)
          when 'bytea' then format('case when %1$I is null then null else decode(md5(ctid::text || %2$L), ''hex'') end as %1$I', col, col)
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          else case when col ~* '_hash$'
                 then format('case when %1$I is null then null else md5(ctid::text || %2$L) || md5(ctid::text || %2$L || ''b'') end as %1$I', col, col)
                 else format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 20) end as %1$I', col, col) end end
      when 'BLOB' then case tn
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          when 'bytea' then format('case when %1$I is null then null else ''\x''::bytea end as %1$I', col)
          else format('case when %1$I is null then null else ''redacted'' end as %1$I', col) end
      when 'PII' then case
          when tn = 'inet' then format('case when %1$I is null then null else ''0.0.0.0''::inet end as %1$I', col)
          when col ~* 'email' then format('case when %1$I is null then null else ''u'' || substr(md5(ctid::text || %2$L), 1, 12) || ''@example.invalid'' end as %1$I', col, col)
          else format('case when %1$I is null then null else ''p'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col) end
      when 'JSONALLOW' then format('case when %1$I is null then null else (case jsonb_typeof(%1$I::jsonb) when ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = '''' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(%1$I::jsonb) e) s) when ''array'' then (select coalesce(jsonb_agg(case when jsonb_typeof(el.v) = ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = ''[].'' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(el.v) e) s) else ''{}''::jsonb end order by el.o), ''[]''::jsonb) from jsonb_array_elements(%1$I::jsonb) with ordinality el(v, o)) else case when exists (select 1 from (values %2$s) a(path, kind) where a.path = ''.'' and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(%1$I::jsonb) = ''number'' when ''BOOL'' then jsonb_typeof(%1$I::jsonb) = ''boolean'' when ''UUID'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end) then %1$I::jsonb else ''{}''::jsonb end end)::%3$s end as %1$I', col, coalesce(allow, '(null::text,null::text)'), tn)
      when 'FREETEXT' then format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col)
    end as expr
  from rh_eff
), rh_tables as (
  select e.t, string_agg(e.expr, ', ' order by e.attnum) as select_list, string_agg(format('%I', e.col), ', ' order by e.attnum) as col_list,
         coalesce(rt.mode, case when e.t ~* '(raw|staging|rate_limit)' then 'SKIP' else 'DATA' end) as proposed_mode,
         rt.mode as reviewed_mode
  from rh_exprs e left join revt rt on rt.t = e.t
  group by e.t, rt.mode
), rh_unreviewed as (
  select 'COLUMN' as kind, t || '.' || col || ' (' || ty || ')' as item,
         case when reviewed_rule is null then 'not in the reviewed list (or its type changed since the review)'
              when eff is null then 'reviewed rule ' || reviewed_rule || ' cannot apply to type ' || ty end as reason
  from rh_eff where eff is null
  union all
  select 'TABLE', t, 'table has no TABLE|name|DATA (or SKIP) line in the reviewed list'
  from rh_tables where reviewed_mode is null or reviewed_mode not in ('DATA','SKIP')
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'invalid path or kind (kind = KEEP|NUM|BOOL|UUID|TS|ENUM:a,b,c; path = key, [].key or .)'
  from revj j where j.kind !~ '^(KEEP|NUM|BOOL|UUID|TS|ENUM:[^|,]+(,[^|,]+)*)$' or j.path !~ '^([.]|([[][]][.])?[A-Za-z][A-Za-z0-9_]{0,40})$'
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'the column exists but its reviewed rule is not JSONALLOW (json/jsonb columns only)'
  from revj j where exists (select 1 from rh_cols c where c.t = j.t and c.col = j.col) and not exists (select 1 from rh_eff e where e.t = j.t and e.col = j.col and e.eff = 'JSONALLOW')
), rh_blocked as (select count(*) > 0 as blocked from rh_unreviewed)
select line from (
  select 1 as o, '\set ON_ERROR_STOP on' as line from rh_blocked where not blocked
  union all select 2, 'begin transaction isolation level repeatable read read only;' from rh_blocked where not blocked
  union all select 4, 'do $rlsguard$ declare bad text := ''''; bypass_flag boolean := (select rolbypassrls from pg_roles where rolname = current_user); r record; begin if bypass_flag then return; end if; for r in select c.relname, c.relforcerowsecurity as frc, (c.relowner = (select oid from pg_roles where rolname = current_user)) as own from pg_class c join pg_namespace n on n.oid = c.relnamespace and n.nspname = ''public'' where c.relkind in (''r'', ''p'') and c.relrowsecurity loop if r.frc or not r.own then bad := bad || '' '' || r.relname; end if; end loop; if bad <> '''' then raise exception ''RLS-GUARD (export): row security applies to this role on:%. The export would be partial. Nothing was exported.'', bad; end if; end $rlsguard$;' from rh_blocked where not blocked
  union all select 5, 'do $seqguard$ declare bad text := ''''; r record; begin for r in select n.nspname || ''.'' || c.relname as s, c.oid from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = ''public'' and c.relkind = ''S'' loop if not has_sequence_privilege(r.oid, ''SELECT'') then bad := bad || '' '' || r.s; end if; end loop; if bad <> '''' then raise exception ''SEQ-GUARD (export): no SELECT on sequence(s):%. Their values would be lost (pg_sequences shows NULL without the privilege). Nothing was exported.'', bad; end if; end $seqguard$;' from rh_blocked where not blocked
  union all select 3, 'do $guard$ declare bad bigint; kinds bigint; begin select count(*) filter (where jsonb_typeof(g.v) in (''object'', ''array'')), count(distinct jsonb_typeof(g.v)) into bad, kinds from (' || kg.kpath || ') g(v) where jsonb_typeof(g.v) <> ''null''; if bad > 0 then raise exception ''KEEP-GUARD: ' || kg.t || '.' || kg.col || ' ' || kg.path || ' is KEEP but holds object or array values; KEEP is for scalar values only. Nothing was exported.''; end if; if kinds > 1 then raise exception ''KEEP-GUARD: ' || kg.t || '.' || kg.col || ' ' || kg.path || ' is KEEP but mixes value types. Nothing was exported.''; end if; end $guard$;' from (
    select j.t, j.col, j.path,
      case when j.path = '.' then 'select x.' || quote_ident(j.col) || '::jsonb as v from public.' || quote_ident(j.t) || ' x'
           when j.path like '[].%' then 'select v from public.' || quote_ident(j.t) || ' x, jsonb_path_query(case when jsonb_typeof(x.' || quote_ident(j.col) || '::jsonb) = ''array'' then x.' || quote_ident(j.col) || '::jsonb else ''[]''::jsonb end, ''$[*]."' || substr(j.path, 4) || '"'') v'
           else 'select v from public.' || quote_ident(j.t) || ' x, jsonb_path_query(case when jsonb_typeof(x.' || quote_ident(j.col) || '::jsonb) = ''object'' then x.' || quote_ident(j.col) || '::jsonb else ''{}''::jsonb end, ''$."' || j.path || '"'') v'
      end as kpath
    from revj j
    where j.kind = 'KEEP' and exists (select 1 from rh_eff e where e.t = j.t and e.col = j.col and e.eff = 'JSONALLOW')
  ) kg, rh_blocked where not blocked
  union all select 10, format('\copy (select %s from public.%I) to ''data/%s.csv'' with (format csv, header true, null ''\N'')', select_list, t, t)
         from rh_tables, rh_blocked where not blocked and reviewed_mode = 'DATA'
  union all select 11, format('-- SKIP-DATA (structure only): public.%I', t) from rh_tables, rh_blocked where not blocked and reviewed_mode = 'SKIP'
  union all select 20, '\copy (select schemaname || ''.'' || sequencename as seq, last_value from pg_sequences where schemaname = ''public'' and last_value is not null) to ''data/_sequences.csv'' with (format csv, header true, null ''\N'')' from rh_blocked where not blocked
  union all select 21, '\copy (select id, created_at, ''u'' || substr(md5(id::text), 1, 12) || ''@example.invalid'' as email from auth.users) to ''data/_auth_users.csv'' with (format csv, header true, null ''\N'')' from rh_blocked where not blocked
  union all select 22, '\copy (select version, name from supabase_migrations.schema_migrations order by version) to ''data/_ledger.csv'' with (format csv, header true, null ''\N'')' from rh_blocked where not blocked
  union all select 23, '\copy (select tbl, n from (' || (select string_agg(format('select %L as tbl, count(*) as n from public.%I', t, t), ' union all ' order by t) from rh_tables where reviewed_mode = 'DATA') || ') q order by tbl) to ''data/_counts.csv'' with (format csv, header true)' from rh_blocked where not blocked
  union all select 90, 'commit;' from rh_blocked where not blocked
  union all select 1, '\set ON_ERROR_STOP on' from rh_blocked where blocked
  union all select 2, '\echo EXPORT BLOCKED: unreviewed columns or tables exist (see unreviewed-columns.txt). Nothing was exported.' from rh_blocked where blocked
  union all select 3, 'select 1/0 as export_blocked_by_unreviewed_columns;' from rh_blocked where blocked
) q order by o, line;

\o load.psql
with rh_cols as (
  select c.relname as t, a.attnum, a.attname as col, format_type(a.atttypid, a.atttypmod) as ty, ty.typname as tn,
    case
      when ty.typname in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb')
       and (a.attname ~* '(secret|token|hmac|password|passwd|credential|api_key|private_key|otp|passcode|salt|nonce)'
            or a.attname in ('code_hash','token_hash','credential_hash','installation_id_hash')) then 'SECRET'
      when ty.typname in ('json','jsonb','text','varchar','bytea')
       and a.attname ~* '(payload|^raw$|raw_|_raw$|response|request_body|headers|body$|qr_payload)'
       and a.attname !~* '(_hash|_fingerprint)$' then 'BLOB'
      when ty.typname in ('text','varchar','bpchar','citext','inet')
       and a.attname ~* '^(full_name|first_name|last_name|phone|phone_number|mobile|email|work_email|contact_email|billing_address|address|guest_name|plate_number|normalized_plate|ip_address|national_id|id_number|passport_number|whatsapp)$' then 'PII'
      when ty.typname in ('text','varchar','bpchar','citext')
       and a.attname ~* '^(description|note|notes|memo|comment|comments|message|remark|remarks|reason)$' then 'FREETEXT'
      when ty.typname in ('json','jsonb') then 'JSONALLOW'
      else 'KEEP'
    end as proposed
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace and n.nspname = 'public'
  join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
  join pg_type ty on ty.oid = a.atttypid
  where c.relkind in ('r','p')
), rev as (
  select split_part(l, '|', 1) as t, split_part(l, '|', 2) as col, split_part(l, '|', 3) as ty, upper(trim(split_part(l, '|', 4))) as rule
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l <> '' and l !~ '^#' and l !~ '^TABLE[|]' and l !~ '^JSONKEEP[|]'
), revj as (
  select split_part(l, '|', 2) as t, split_part(l, '|', 3) as col, split_part(l, '|', 4) as path, trim(split_part(l, '|', 5)) as kind
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^JSONKEEP[|]'
), revt as (
  select split_part(l, '|', 2) as t, upper(trim(split_part(l, '|', 3))) as mode
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^TABLE[|]'
), rh_eff as (
  select k.t, k.attnum, k.col, k.ty, k.tn, k.proposed, r.rule as reviewed_rule,
    (select string_agg(format('(%L,%L)', j.path, j.kind), ',') from revj j where j.t = k.t and j.col = k.col) as allow,
    case
      when r.rule is null then null
      when r.rule = 'KEEP' then 'KEEP'
      when r.rule = 'SECRET'   and k.tn in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb') then 'SECRET'
      when r.rule = 'BLOB'     and k.tn in ('json','jsonb','text','varchar','bytea') then 'BLOB'
      when r.rule = 'PII'      and k.tn in ('text','varchar','bpchar','citext','inet') then 'PII'
      when r.rule = 'FREETEXT' and k.tn in ('text','varchar','bpchar','citext') then 'FREETEXT'
      when r.rule = 'JSONALLOW' and k.tn in ('json','jsonb') then 'JSONALLOW'
      else null
    end as eff
  from rh_cols k left join rev r on r.t = k.t and r.col = k.col and r.ty = k.ty
), rh_exprs as (
  select t, attnum, col, eff, tn, allow,
    case eff
      when 'KEEP' then format('%I', col)
      when 'SECRET' then case tn
          when 'uuid'  then format('case when %1$I is null then null else md5(ctid::text || %2$L)::uuid end as %1$I', col, col)
          when 'bytea' then format('case when %1$I is null then null else decode(md5(ctid::text || %2$L), ''hex'') end as %1$I', col, col)
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          else case when col ~* '_hash$'
                 then format('case when %1$I is null then null else md5(ctid::text || %2$L) || md5(ctid::text || %2$L || ''b'') end as %1$I', col, col)
                 else format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 20) end as %1$I', col, col) end end
      when 'BLOB' then case tn
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          when 'bytea' then format('case when %1$I is null then null else ''\x''::bytea end as %1$I', col)
          else format('case when %1$I is null then null else ''redacted'' end as %1$I', col) end
      when 'PII' then case
          when tn = 'inet' then format('case when %1$I is null then null else ''0.0.0.0''::inet end as %1$I', col)
          when col ~* 'email' then format('case when %1$I is null then null else ''u'' || substr(md5(ctid::text || %2$L), 1, 12) || ''@example.invalid'' end as %1$I', col, col)
          else format('case when %1$I is null then null else ''p'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col) end
      when 'JSONALLOW' then format('case when %1$I is null then null else (case jsonb_typeof(%1$I::jsonb) when ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = '''' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(%1$I::jsonb) e) s) when ''array'' then (select coalesce(jsonb_agg(case when jsonb_typeof(el.v) = ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = ''[].'' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(el.v) e) s) else ''{}''::jsonb end order by el.o), ''[]''::jsonb) from jsonb_array_elements(%1$I::jsonb) with ordinality el(v, o)) else case when exists (select 1 from (values %2$s) a(path, kind) where a.path = ''.'' and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(%1$I::jsonb) = ''number'' when ''BOOL'' then jsonb_typeof(%1$I::jsonb) = ''boolean'' when ''UUID'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end) then %1$I::jsonb else ''{}''::jsonb end end)::%3$s end as %1$I', col, coalesce(allow, '(null::text,null::text)'), tn)
      when 'FREETEXT' then format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col)
    end as expr
  from rh_eff
), rh_tables as (
  select e.t, string_agg(e.expr, ', ' order by e.attnum) as select_list, string_agg(format('%I', e.col), ', ' order by e.attnum) as col_list,
         coalesce(rt.mode, case when e.t ~* '(raw|staging|rate_limit)' then 'SKIP' else 'DATA' end) as proposed_mode,
         rt.mode as reviewed_mode
  from rh_exprs e left join revt rt on rt.t = e.t
  group by e.t, rt.mode
), rh_unreviewed as (
  select 'COLUMN' as kind, t || '.' || col || ' (' || ty || ')' as item,
         case when reviewed_rule is null then 'not in the reviewed list (or its type changed since the review)'
              when eff is null then 'reviewed rule ' || reviewed_rule || ' cannot apply to type ' || ty end as reason
  from rh_eff where eff is null
  union all
  select 'TABLE', t, 'table has no TABLE|name|DATA (or SKIP) line in the reviewed list'
  from rh_tables where reviewed_mode is null or reviewed_mode not in ('DATA','SKIP')
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'invalid path or kind (kind = KEEP|NUM|BOOL|UUID|TS|ENUM:a,b,c; path = key, [].key or .)'
  from revj j where j.kind !~ '^(KEEP|NUM|BOOL|UUID|TS|ENUM:[^|,]+(,[^|,]+)*)$' or j.path !~ '^([.]|([[][]][.])?[A-Za-z][A-Za-z0-9_]{0,40})$'
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'the column exists but its reviewed rule is not JSONALLOW (json/jsonb columns only)'
  from revj j where exists (select 1 from rh_cols c where c.t = j.t and c.col = j.col) and not exists (select 1 from rh_eff e where e.t = j.t and e.col = j.col and e.eff = 'JSONALLOW')
), rh_blocked as (select count(*) > 0 as blocked from rh_unreviewed)
select line from (
  select 1 as o, '\set ON_ERROR_STOP on' as line from rh_blocked where not blocked
  union all select 2, 'set session_replication_role = replica;' from rh_blocked where not blocked
  union all select 10, '\copy public.' || quote_ident(t) || ' (' || col_list || ') from ''data/' || t || '.csv'' with (format csv, header true, null ''\N'')'
         from rh_tables, rh_blocked where not blocked and reviewed_mode = 'DATA'
  union all select 20, 'create temp table rh_seq (seq text, last_value bigint);' from rh_blocked where not blocked
  union all select 21, '\copy rh_seq from ''data/_sequences.csv'' with (format csv, header true, null ''\N'')' from rh_blocked where not blocked
  union all select 22, 'select setval(seq::regclass, last_value) from rh_seq;' from rh_blocked where not blocked
  union all select 23, 'create temp table rh_users (id uuid, created_at timestamptz, email text);' from rh_blocked where not blocked
  union all select 24, '\copy rh_users from ''data/_auth_users.csv'' with (format csv, header true, null ''\N'')' from rh_blocked where not blocked
  union all select 25, 'insert into auth.users (id, created_at, email, aud, role, instance_id) select id, created_at, email, ''authenticated'', ''authenticated'', ''00000000-0000-0000-0000-000000000000'' from rh_users on conflict do nothing;' from rh_blocked where not blocked
  union all select 26, 'create schema if not exists supabase_migrations;' from rh_blocked where not blocked
  union all select 27, 'create table if not exists supabase_migrations.schema_migrations (version text not null primary key, statements text[], name text);' from rh_blocked where not blocked
  union all select 28, 'create temp table rh_ledger (version text, name text);' from rh_blocked where not blocked
  union all select 29, '\copy rh_ledger from ''data/_ledger.csv'' with (format csv, header true, null ''\N'')' from rh_blocked where not blocked
  union all select 30, 'insert into supabase_migrations.schema_migrations (version, name) select version, name from rh_ledger on conflict (version) do nothing;' from rh_blocked where not blocked
  union all select 31, 'reset session_replication_role;' from rh_blocked where not blocked
  union all select 32, 'show session_replication_role;' from rh_blocked where not blocked
  union all select 33, 'analyze;' from rh_blocked where not blocked
  union all select 34, '\echo LOAD DONE: now run load-verify.psql (relations, counts, sequences) before anything else' from rh_blocked where not blocked
  union all select 1, '\echo LOAD BLOCKED: unreviewed columns or tables exist (see unreviewed-columns.txt)' from rh_blocked where blocked
  union all select 2, 'select 1/0 as load_blocked_by_unreviewed_columns;' from rh_blocked where blocked
) q order by o, line;

\o rule-report.txt
with rh_cols as (
  select c.relname as t, a.attnum, a.attname as col, format_type(a.atttypid, a.atttypmod) as ty, ty.typname as tn,
    case
      when ty.typname in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb')
       and (a.attname ~* '(secret|token|hmac|password|passwd|credential|api_key|private_key|otp|passcode|salt|nonce)'
            or a.attname in ('code_hash','token_hash','credential_hash','installation_id_hash')) then 'SECRET'
      when ty.typname in ('json','jsonb','text','varchar','bytea')
       and a.attname ~* '(payload|^raw$|raw_|_raw$|response|request_body|headers|body$|qr_payload)'
       and a.attname !~* '(_hash|_fingerprint)$' then 'BLOB'
      when ty.typname in ('text','varchar','bpchar','citext','inet')
       and a.attname ~* '^(full_name|first_name|last_name|phone|phone_number|mobile|email|work_email|contact_email|billing_address|address|guest_name|plate_number|normalized_plate|ip_address|national_id|id_number|passport_number|whatsapp)$' then 'PII'
      when ty.typname in ('text','varchar','bpchar','citext')
       and a.attname ~* '^(description|note|notes|memo|comment|comments|message|remark|remarks|reason)$' then 'FREETEXT'
      when ty.typname in ('json','jsonb') then 'JSONALLOW'
      else 'KEEP'
    end as proposed
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace and n.nspname = 'public'
  join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
  join pg_type ty on ty.oid = a.atttypid
  where c.relkind in ('r','p')
), rev as (
  select split_part(l, '|', 1) as t, split_part(l, '|', 2) as col, split_part(l, '|', 3) as ty, upper(trim(split_part(l, '|', 4))) as rule
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l <> '' and l !~ '^#' and l !~ '^TABLE[|]' and l !~ '^JSONKEEP[|]'
), revj as (
  select split_part(l, '|', 2) as t, split_part(l, '|', 3) as col, split_part(l, '|', 4) as path, trim(split_part(l, '|', 5)) as kind
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^JSONKEEP[|]'
), revt as (
  select split_part(l, '|', 2) as t, upper(trim(split_part(l, '|', 3))) as mode
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^TABLE[|]'
), rh_eff as (
  select k.t, k.attnum, k.col, k.ty, k.tn, k.proposed, r.rule as reviewed_rule,
    (select string_agg(format('(%L,%L)', j.path, j.kind), ',') from revj j where j.t = k.t and j.col = k.col) as allow,
    case
      when r.rule is null then null
      when r.rule = 'KEEP' then 'KEEP'
      when r.rule = 'SECRET'   and k.tn in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb') then 'SECRET'
      when r.rule = 'BLOB'     and k.tn in ('json','jsonb','text','varchar','bytea') then 'BLOB'
      when r.rule = 'PII'      and k.tn in ('text','varchar','bpchar','citext','inet') then 'PII'
      when r.rule = 'FREETEXT' and k.tn in ('text','varchar','bpchar','citext') then 'FREETEXT'
      when r.rule = 'JSONALLOW' and k.tn in ('json','jsonb') then 'JSONALLOW'
      else null
    end as eff
  from rh_cols k left join rev r on r.t = k.t and r.col = k.col and r.ty = k.ty
), rh_exprs as (
  select t, attnum, col, eff, tn, allow,
    case eff
      when 'KEEP' then format('%I', col)
      when 'SECRET' then case tn
          when 'uuid'  then format('case when %1$I is null then null else md5(ctid::text || %2$L)::uuid end as %1$I', col, col)
          when 'bytea' then format('case when %1$I is null then null else decode(md5(ctid::text || %2$L), ''hex'') end as %1$I', col, col)
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          else case when col ~* '_hash$'
                 then format('case when %1$I is null then null else md5(ctid::text || %2$L) || md5(ctid::text || %2$L || ''b'') end as %1$I', col, col)
                 else format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 20) end as %1$I', col, col) end end
      when 'BLOB' then case tn
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          when 'bytea' then format('case when %1$I is null then null else ''\x''::bytea end as %1$I', col)
          else format('case when %1$I is null then null else ''redacted'' end as %1$I', col) end
      when 'PII' then case
          when tn = 'inet' then format('case when %1$I is null then null else ''0.0.0.0''::inet end as %1$I', col)
          when col ~* 'email' then format('case when %1$I is null then null else ''u'' || substr(md5(ctid::text || %2$L), 1, 12) || ''@example.invalid'' end as %1$I', col, col)
          else format('case when %1$I is null then null else ''p'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col) end
      when 'JSONALLOW' then format('case when %1$I is null then null else (case jsonb_typeof(%1$I::jsonb) when ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = '''' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(%1$I::jsonb) e) s) when ''array'' then (select coalesce(jsonb_agg(case when jsonb_typeof(el.v) = ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = ''[].'' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(el.v) e) s) else ''{}''::jsonb end order by el.o), ''[]''::jsonb) from jsonb_array_elements(%1$I::jsonb) with ordinality el(v, o)) else case when exists (select 1 from (values %2$s) a(path, kind) where a.path = ''.'' and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(%1$I::jsonb) = ''number'' when ''BOOL'' then jsonb_typeof(%1$I::jsonb) = ''boolean'' when ''UUID'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end) then %1$I::jsonb else ''{}''::jsonb end end)::%3$s end as %1$I', col, coalesce(allow, '(null::text,null::text)'), tn)
      when 'FREETEXT' then format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col)
    end as expr
  from rh_eff
), rh_tables as (
  select e.t, string_agg(e.expr, ', ' order by e.attnum) as select_list, string_agg(format('%I', e.col), ', ' order by e.attnum) as col_list,
         coalesce(rt.mode, case when e.t ~* '(raw|staging|rate_limit)' then 'SKIP' else 'DATA' end) as proposed_mode,
         rt.mode as reviewed_mode
  from rh_exprs e left join revt rt on rt.t = e.t
  group by e.t, rt.mode
), rh_unreviewed as (
  select 'COLUMN' as kind, t || '.' || col || ' (' || ty || ')' as item,
         case when reviewed_rule is null then 'not in the reviewed list (or its type changed since the review)'
              when eff is null then 'reviewed rule ' || reviewed_rule || ' cannot apply to type ' || ty end as reason
  from rh_eff where eff is null
  union all
  select 'TABLE', t, 'table has no TABLE|name|DATA (or SKIP) line in the reviewed list'
  from rh_tables where reviewed_mode is null or reviewed_mode not in ('DATA','SKIP')
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'invalid path or kind (kind = KEEP|NUM|BOOL|UUID|TS|ENUM:a,b,c; path = key, [].key or .)'
  from revj j where j.kind !~ '^(KEEP|NUM|BOOL|UUID|TS|ENUM:[^|,]+(,[^|,]+)*)$' or j.path !~ '^([.]|([[][]][.])?[A-Za-z][A-Za-z0-9_]{0,40})$'
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'the column exists but its reviewed rule is not JSONALLOW (json/jsonb columns only)'
  from revj j where exists (select 1 from rh_cols c where c.t = j.t and c.col = j.col) and not exists (select 1 from rh_eff e where e.t = j.t and e.col = j.col and e.eff = 'JSONALLOW')
), rh_blocked as (select count(*) > 0 as blocked from rh_unreviewed)
select line from (
  select 0 as o, '# RULE-REPORT: EVERY public column and table, KEEP included. Format  table|column|type|RULE   and   TABLE|name|DATA   (or SKIP)' as line, '' as k1, '' as k2
  union all select 1, '# proposed by name patterns from the catalog (no data read); review, edit a rule if needed, save as reviewed-columns.sql (see reviewed-candidate.sql). JSONALLOW columns need JSONKEEP|table|column|path|kind lines or they export only {"_redacted": n}', '', ''
  union all select 2, '# ' || proposed || ' columns: ' || count(*), '', '' from rh_cols group by proposed
  union all select 3, '# columns: ' || (select count(*) from rh_cols) || ' | tables: ' || (select count(*) from rh_tables) || ' | currently UNREVIEWED items: ' || (select count(*) from rh_unreviewed), '', ''
  union all select 10, 'TABLE|' || t || '|' || proposed_mode, t, '' from rh_tables
  union all select 20, t || '|' || col || '|' || ty || '|' || proposed, t, lpad(attnum::text, 5, '0') from rh_cols
) q order by o, k1, k2, line;

\o reviewed-candidate.sql
select 'select $rev$';
with rh_cols as (
  select c.relname as t, a.attnum, a.attname as col, format_type(a.atttypid, a.atttypmod) as ty, ty.typname as tn,
    case
      when ty.typname in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb')
       and (a.attname ~* '(secret|token|hmac|password|passwd|credential|api_key|private_key|otp|passcode|salt|nonce)'
            or a.attname in ('code_hash','token_hash','credential_hash','installation_id_hash')) then 'SECRET'
      when ty.typname in ('json','jsonb','text','varchar','bytea')
       and a.attname ~* '(payload|^raw$|raw_|_raw$|response|request_body|headers|body$|qr_payload)'
       and a.attname !~* '(_hash|_fingerprint)$' then 'BLOB'
      when ty.typname in ('text','varchar','bpchar','citext','inet')
       and a.attname ~* '^(full_name|first_name|last_name|phone|phone_number|mobile|email|work_email|contact_email|billing_address|address|guest_name|plate_number|normalized_plate|ip_address|national_id|id_number|passport_number|whatsapp)$' then 'PII'
      when ty.typname in ('text','varchar','bpchar','citext')
       and a.attname ~* '^(description|note|notes|memo|comment|comments|message|remark|remarks|reason)$' then 'FREETEXT'
      when ty.typname in ('json','jsonb') then 'JSONALLOW'
      else 'KEEP'
    end as proposed
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace and n.nspname = 'public'
  join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped and a.attgenerated = ''
  join pg_type ty on ty.oid = a.atttypid
  where c.relkind in ('r','p')
), rev as (
  select split_part(l, '|', 1) as t, split_part(l, '|', 2) as col, split_part(l, '|', 3) as ty, upper(trim(split_part(l, '|', 4))) as rule
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l <> '' and l !~ '^#' and l !~ '^TABLE[|]' and l !~ '^JSONKEEP[|]'
), revj as (
  select split_part(l, '|', 2) as t, split_part(l, '|', 3) as col, split_part(l, '|', 4) as path, trim(split_part(l, '|', 5)) as kind
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^JSONKEEP[|]'
), revt as (
  select split_part(l, '|', 2) as t, upper(trim(split_part(l, '|', 3))) as mode
  from regexp_split_to_table(:'reviewed', E'\r?\n') as l
  where l ~ '^TABLE[|]'
), rh_eff as (
  select k.t, k.attnum, k.col, k.ty, k.tn, k.proposed, r.rule as reviewed_rule,
    (select string_agg(format('(%L,%L)', j.path, j.kind), ',') from revj j where j.t = k.t and j.col = k.col) as allow,
    case
      when r.rule is null then null
      when r.rule = 'KEEP' then 'KEEP'
      when r.rule = 'SECRET'   and k.tn in ('text','varchar','bpchar','citext','bytea','uuid','json','jsonb') then 'SECRET'
      when r.rule = 'BLOB'     and k.tn in ('json','jsonb','text','varchar','bytea') then 'BLOB'
      when r.rule = 'PII'      and k.tn in ('text','varchar','bpchar','citext','inet') then 'PII'
      when r.rule = 'FREETEXT' and k.tn in ('text','varchar','bpchar','citext') then 'FREETEXT'
      when r.rule = 'JSONALLOW' and k.tn in ('json','jsonb') then 'JSONALLOW'
      else null
    end as eff
  from rh_cols k left join rev r on r.t = k.t and r.col = k.col and r.ty = k.ty
), rh_exprs as (
  select t, attnum, col, eff, tn, allow,
    case eff
      when 'KEEP' then format('%I', col)
      when 'SECRET' then case tn
          when 'uuid'  then format('case when %1$I is null then null else md5(ctid::text || %2$L)::uuid end as %1$I', col, col)
          when 'bytea' then format('case when %1$I is null then null else decode(md5(ctid::text || %2$L), ''hex'') end as %1$I', col, col)
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          else case when col ~* '_hash$'
                 then format('case when %1$I is null then null else md5(ctid::text || %2$L) || md5(ctid::text || %2$L || ''b'') end as %1$I', col, col)
                 else format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 20) end as %1$I', col, col) end end
      when 'BLOB' then case tn
          when 'jsonb' then format('case when %1$I is null then null else ''{}''::jsonb end as %1$I', col)
          when 'json'  then format('case when %1$I is null then null else ''{}''::json end as %1$I', col)
          when 'bytea' then format('case when %1$I is null then null else ''\x''::bytea end as %1$I', col)
          else format('case when %1$I is null then null else ''redacted'' end as %1$I', col) end
      when 'PII' then case
          when tn = 'inet' then format('case when %1$I is null then null else ''0.0.0.0''::inet end as %1$I', col)
          when col ~* 'email' then format('case when %1$I is null then null else ''u'' || substr(md5(ctid::text || %2$L), 1, 12) || ''@example.invalid'' end as %1$I', col, col)
          else format('case when %1$I is null then null else ''p'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col) end
      when 'JSONALLOW' then format('case when %1$I is null then null else (case jsonb_typeof(%1$I::jsonb) when ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = '''' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(%1$I::jsonb) e) s) when ''array'' then (select coalesce(jsonb_agg(case when jsonb_typeof(el.v) = ''object'' then (select coalesce(jsonb_object_agg(s.k, s.v) filter (where s.ok), ''{}''::jsonb) || case when count(*) filter (where not s.ok) > 0 then jsonb_build_object(''_redacted'', count(*) filter (where not s.ok)) else ''{}''::jsonb end from (select e.key as k, e.value as v, (jsonb_typeof(e.value) = ''null'' or exists (select 1 from (values %2$s) a(path, kind) where a.path = ''[].'' || e.key and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(e.value) = ''number'' when ''BOOL'' then jsonb_typeof(e.value) = ''boolean'' when ''UUID'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(e.value) = ''string'' and (e.value #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end)) as ok from jsonb_each(el.v) e) s) else ''{}''::jsonb end order by el.o), ''[]''::jsonb) from jsonb_array_elements(%1$I::jsonb) with ordinality el(v, o)) else case when exists (select 1 from (values %2$s) a(path, kind) where a.path = ''.'' and case split_part(a.kind, '':'', 1) when ''KEEP'' then true when ''NUM'' then jsonb_typeof(%1$I::jsonb) = ''number'' when ''BOOL'' then jsonb_typeof(%1$I::jsonb) = ''boolean'' when ''UUID'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'' when ''TS'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9:.]+(Z|[+-][0-9:]+)?)?$'' when ''ENUM'' then jsonb_typeof(%1$I::jsonb) = ''string'' and (%1$I::jsonb #>> ''{}'') = any (string_to_array(substr(a.kind, 6), '','')) else false end) then %1$I::jsonb else ''{}''::jsonb end end)::%3$s end as %1$I', col, coalesce(allow, '(null::text,null::text)'), tn)
      when 'FREETEXT' then format('case when %1$I is null then null else ''x'' || substr(md5(ctid::text || %2$L), 1, 12) end as %1$I', col, col)
    end as expr
  from rh_eff
), rh_tables as (
  select e.t, string_agg(e.expr, ', ' order by e.attnum) as select_list, string_agg(format('%I', e.col), ', ' order by e.attnum) as col_list,
         coalesce(rt.mode, case when e.t ~* '(raw|staging|rate_limit)' then 'SKIP' else 'DATA' end) as proposed_mode,
         rt.mode as reviewed_mode
  from rh_exprs e left join revt rt on rt.t = e.t
  group by e.t, rt.mode
), rh_unreviewed as (
  select 'COLUMN' as kind, t || '.' || col || ' (' || ty || ')' as item,
         case when reviewed_rule is null then 'not in the reviewed list (or its type changed since the review)'
              when eff is null then 'reviewed rule ' || reviewed_rule || ' cannot apply to type ' || ty end as reason
  from rh_eff where eff is null
  union all
  select 'TABLE', t, 'table has no TABLE|name|DATA (or SKIP) line in the reviewed list'
  from rh_tables where reviewed_mode is null or reviewed_mode not in ('DATA','SKIP')
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'invalid path or kind (kind = KEEP|NUM|BOOL|UUID|TS|ENUM:a,b,c; path = key, [].key or .)'
  from revj j where j.kind !~ '^(KEEP|NUM|BOOL|UUID|TS|ENUM:[^|,]+(,[^|,]+)*)$' or j.path !~ '^([.]|([[][]][.])?[A-Za-z][A-Za-z0-9_]{0,40})$'
  union all
  select 'JSONKEEP', j.t || '.' || j.col || ' ' || j.path || ' ' || j.kind, 'the column exists but its reviewed rule is not JSONALLOW (json/jsonb columns only)'
  from revj j where exists (select 1 from rh_cols c where c.t = j.t and c.col = j.col) and not exists (select 1 from rh_eff e where e.t = j.t and e.col = j.col and e.eff = 'JSONALLOW')
), rh_blocked as (select count(*) > 0 as blocked from rh_unreviewed)
select line from (
  select 10 as o, 'TABLE|' || t || '|' || proposed_mode as line, t as k1, '' as k2 from rh_tables
  union all select 20, t || '|' || col || '|' || ty || '|' || proposed, t, lpad(attnum::text, 5, '0') from rh_cols
) q order by o, k1, k2, line;
select '$rev$ as reviewed \gset';

